class Solution { public String[] getFolderNames(String[] names){Map<String,Integer> next=new HashMap<>();String[] answer=new String[names.length];for(int i=0;i<names.length;i++){String name=names[i];if(!next.containsKey(name)){answer[i]=name;next.put(name,1);}else{int k=next.get(name);String candidate=name+"("+k+")";while(next.containsKey(candidate))candidate=name+"("+(++k)+")";answer[i]=candidate;next.put(name,k+1);next.put(candidate,1);}}return answer;} }
